// Finite support-content improvements: no payment, eligibility or fulfilment change.
export const complaintStart='<section data-support-content="2026-10-10"><h2>Make a complaint</h2><p><a href="/contact?type=complaint">Contact SHIFT about a complaint</a>. Start your message with “Complaint” and tell us what happened, when it happened and what you would like us to put right. Include an existing reference if you have one and the best email address for a reply.</p><p>Keep a copy of your message. Do not include passwords, full card details or medical documents in the general contact form. If your complaint is about another clinic or pharmacy, use that provider’s own complaints route; SHIFT cannot investigate its private records.</p></section>';
export const paymentNote='<section data-support-content="2026-10-10"><h2>Make a payment query easier to resolve</h2><p>Check the seller named on your order confirmation and the payment description on your statement. In your message, give the payment date, amount, order reference if available and whether you are asking to cancel, correct a charge or check a refund. Do not send a bank statement or card number through the general form.</p><p>Keep a dated copy of your cancellation request and ask the seller to confirm the order status, any amount being refunded and how you will recognise the refund. This does not mean your cancellation rights depend on the seller agreeing. SHIFT cannot promise another seller’s decision or processing time.</p></section>';
export function supportContent(html,path){
 if(path==='/complaints')html=html.replace(/<h2>What happens next<\/h2>/,complaintStart+'<h2>What happens next</h2>').replace('This route is not an emergency or clinical service: use NHS 111 or 999 where appropriate.','This route is not an emergency or clinical service. For urgent help, use <a href="/help">the routes for your part of the UK</a>; call 999 in a life-threatening emergency.');
 if(path==='/contact')html=html.replace('Questions, support, partnerships or press—send the detail securely and it will reach the Shift team.','Questions, support, partnerships or press—tell us what you need help with. For a complaint, start your message with “Complaint”. For a payment query, choose “My order” and include the payment date and reference.').replace('Call 999 in an emergency, or use NHS 111 for urgent medical help that is not life-threatening.','Call 999 in a life-threatening emergency. For other urgent help, choose the route for your part of the UK.').replace('href="https://111.nhs.uk/"','href="/help"').replace('Open NHS 111 →','Find urgent help →');
 if(path==='/terms-of-sale'||path==='/refunds')html=html.replace('</div></section></div></main>',paymentNote+'</div></section></div></main>');
 return html;
}